<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (one primitive per visible element) ──────────────────────
// x-axis → Line + ConeGeometry arrowhead, #222, fig +X → world +X, len 7
// y-axis → Line + Cone, fig +Y → world +Z, len 7
// z-axis → Line + Cone, fig +Z → world +Y, len 7
// P       → SphereGeometry(0.09) black at (ρ sinφ cosθ, ρ sinφ sinθ, ρ cosφ)
// P label → two-line addLabel right of P: 'P(x, y, z)' / 'P(ρ, θ, φ)'
// ρ line  → CylinderGeometry origin→P, #1a5caa, radius 0.03
// φ arc   → sampled thin Line (r=1.2) + cone arrowhead, z-axis → OP
// θ arc   → sampled thin Line (r=1.2) in xy-plane + cone arrowhead, x → ground seg
// z drop  → dashed Line #e07b2a, P → (x, y, 0)
// r line  → dashed Line #e07b2a, origin → (x, y, 0)
// square  → 1-pt Line loop at foot, side 0.28
// helpers → 3 dashed grey lines P→axis (visible in rectangular mode)
*/
const UPW = new THREE.Vector3(0, 1, 0);      // figure +z in world space
const ORIGIN = new THREE.Vector3(0, 0, 0);
const AXIS_LEN = 7, ARC_R = 1.2, SQ = 0.28;
const BLUE = 0x1a5caa, ORANGE = 0xe07b2a, HILITE = 0xff7f00,
      DIMR = 0xb9cfe3, GREY = 0xbbbbbb, DARK = 0x333333;

const state = { rho: 4, theta: 40, phi: 50 };
let mode = 'sph';   // 'rect' | 'cyl' | 'sph'

/* ── Axes ─────────────────────────────────────────────────────────────── */
function makeAxis(fx, fy, fz) {
  const dir = new THREE.Vector3(fx, fz, fy).normalize();  // (x,z,y): fig→world
  const g = new THREE.Group();
  const mat = new THREE.LineBasicMaterial({ color: 0x222222 });
  g.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(
      [ORIGIN.clone(), dir.clone().multiplyScalar(AXIS_LEN)]), mat));
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.10, 0.30, 16),
    new THREE.MeshBasicMaterial({ color: 0x222222 }));
  cone.position.copy(dir).multiplyScalar(AXIS_LEN + 0.15);
  cone.quaternion.setFromUnitVectors(UPW, dir);
  g.add(cone);
  scene.add(g);
  return dir.clone().multiplyScalar(AXIS_LEN + 0.45);
}
const ptX = makeAxis(1, 0, 0), ptY = makeAxis(0, 1, 0), ptZ = makeAxis(0, 0, 1);

/* ── Static / reactive materials and meshes ───────────────────────────── */
const pMesh = new THREE.Mesh(new THREE.SphereGeometry(0.09, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));          scene.add(pMesh);

const rhoMat = new THREE.MeshBasicMaterial({ color: BLUE, transparent: true });
const rhoCyl = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1, 12), rhoMat);
scene.add(rhoCyl);

const orangeDashMat = new THREE.LineDashedMaterial({ color: ORANGE, dashSize: 0.18, gapSize: 0.11, transparent: true });
const dropLine   = new THREE.Line(new THREE.BufferGeometry(), orangeDashMat);
const groundLine = new THREE.Line(new THREE.BufferGeometry(), orangeDashMat);
scene.add(dropLine, groundLine);

const sqMat = new THREE.LineBasicMaterial({ color: ORANGE, transparent: true });
const squareLine = new THREE.Line(new THREE.BufferGeometry(), sqMat);
scene.add(squareLine);

const phiMat   = new THREE.LineBasicMaterial({ color: DARK });
const thetaMat = new THREE.LineBasicMaterial({ color: DARK });
const phiLine   = new THREE.Line(new THREE.BufferGeometry(), phiMat);
const thetaLine = new THREE.Line(new THREE.BufferGeometry(), thetaMat);
scene.add(phiLine, thetaLine);

function makeArcArrow(mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.15, 10), mat);
  scene.add(m); return m;
}
const phiArrow = makeArcArrow(phiMat), thetaArrow = makeArcArrow(thetaMat);

const helperMat = new THREE.LineDashedMaterial({ color: 0x999999, dashSize: 0.14, gapSize: 0.10, transparent: true });
const helpers = [0, 1, 2].map(() => {
  const l = new THREE.Line(new THREE.BufferGeometry(), helperMat);
  l.visible = false; scene.add(l); return l;
});

function setDashed(line, a, b) {
  line.geometry.setFromPoints([a.clone(), b.clone()]);
  line.computeLineDistances();
}
const _dir = new THREE.Vector3();
function setRod(mesh, a, b) {
  _dir.subVectors(b, a);
  const len = Math.max(_dir.length(), 1e-6);
  mesh.position.copy(a).addScaledVector(_dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UPW, _dir.clone().normalize());
  mesh.scale.set(1, len, 1);
}

/* ── Reactive update ──────────────────────────────────────────────────── */
function figCoords() {
  const th = THREE.MathUtils.degToRad(state.theta);
  const ph = THREE.MathUtils.degToRad(state.phi);
  const r = state.rho * Math.sin(ph);
  return { x: r * Math.cos(th), y: r * Math.sin(th), z: state.rho * Math.cos(ph), r, th, ph };
}

function update() {
  const { x, y, z, r, th, ph } = figCoords();
  const Pw = new THREE.Vector3(x, z, y);          // fig (x,y,z) → world (x, z, y)
  const Fw = new THREE.Vector3(x, 0, y);          // foot (x, y, 0)
  pMesh.position.copy(Pw);
  rhoCyl.visible = state.rho > 0.05;
  if (rhoCyl.visible) setRod(rhoCyl, ORIGIN, Pw);
  setDashed(dropLine, Pw, Fw);
  setDashed(groundLine, ORIGIN, Fw);

  // right-angle square at the foot
  const u = r > 1e-6 ? Fw.clone().negate().normalize() : new THREE.Vector3(1, 0, 0);
  const v = UPW.clone().multiplyScalar(z >= 0 ? 1 : -1).multiplyScalar(SQ);
  const uS = u.clone().multiplyScalar(SQ);
  squareLine.geometry.setFromPoints([
    Fw.clone(), Fw.clone().add(uS), Fw.clone().add(uS).clone().add(v),
    Fw.clone().add(v), Fw.clone()]);

  // φ arc (z-axis → OP), radius ARC_R
  const op = Pw.clone().normalize();
  let perp = op.clone().addScaledVector(UPW, -op.dot(UPW));
  if (perp.lengthSq() < 1e-8) perp.set(1, 0, 0);
  perp.normalize();
  const Np = Math.max(2, Math.round(80 * ph));
  const phiPts = [];
  for (let i = 0; i <= Np; i++) {
    const t = ph * i / Np;
    phiPts.push(UPW.clone().multiplyScalar(Math.cos(t))
      .addScaledVector(perp, Math.sin(t)).multiplyScalar(ARC_R));
  }
  phiLine.geometry.setFromPoints(phiPts);
  {
    const T = UPW.clone().multiplyScalar(-Math.sin(ph))
      .addScaledVector(perp, Math.cos(ph)).normalize();
    phiArrow.quaternion.setFromUnitVectors(UPW, T);
    phiArrow.position.copy(UPW.clone().multiplyScalar(Math.cos(ph))
      .addScaledVector(perp, Math.sin(ph)).multiplyScalar(ARC_R));
    lblPhi.pos.copy(UPW.clone().multiplyScalar(Math.cos(ph / 2))
      .addScaledVector(perp, Math.sin(ph / 2)).multiplyScalar(ARC_R * 1.5));
  }

  // θ arc (x-axis → ground segment) in the xy-plane
  const Nt = Math.max(2, Math.round(80 * th));
  const thetaPts = [];
  for (let i = 0; i <= Nt; i++) {
    const a = th * i / Nt;
    thetaPts.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a)).multiplyScalar(ARC_R));
  }
  thetaLine.geometry.setFromPoints(thetaPts);
  {
    const T = new THREE.Vector3(-Math.sin(th), 0, Math.cos(th)).normalize();
    thetaArrow.quaternion.setFromUnitVectors(UPW, T);
    thetaArrow.position.set(Math.cos(th), 0, Math.sin(th)).multiplyScalar(ARC_R);
    lblTheta.pos.set(Math.cos(th / 2), 0, Math.sin(th / 2)).multiplyScalar(ARC_R * 1.5);
  }

  // labels that track the point
  lblP.pos.copy(Pw);
  lblRho.pos.copy(Pw).multiplyScalar(0.5).addScaledVector(UPW, 0.32);
  lblZ.pos.copy(Pw).lerp(Fw, 0.5);
  lblR.pos.copy(Fw).multiplyScalar(0.5);

  // rectangular helper lines: P → each axis
  setDashed(helpers[0], Pw, new THREE.Vector3(x, 0, 0));
  setDashed(helpers[1], Pw, new THREE.Vector3(0, 0, y));
  setDashed(helpers[2], Pw, new THREE.Vector3(0, z, 0));
  renderReadout();
}

/* ── Mode highlight + readout ─────────────────────────────────────────── */
const readout = document.getElementById('readout');
function renderReadout() {
  const { x, y, z, r } = figCoords();
  const f = (v, d = 2) => v.toFixed(d);
  readout.innerHTML =
    mode === 'rect'  ? `x = ${f(x)}<br>y = ${f(y)}<br>z = ${f(z)}` :
    mode === 'cyl'   ? `r = ${f(r)}<br>θ = ${f(state.theta, 0)}°<br>z = ${f(z)}` :
                       `ρ = ${f(state.rho)}<br>θ = ${f(state.theta, 0)}°<br>φ = ${f(state.phi, 0)}°`;
}
function setMode(m) {
  mode = m;
  const sph = m === 'sph', cyl = m === 'cyl', rect = m === 'rect';
  [['cs-rect', 'rect'], ['cs-cyl', 'cyl'], ['cs-sph', 'sph']].forEach(([id, k]) =>
    document.getElementById(id).classList.toggle('active', k === m));
  rhoMat.color.set(sph ? BLUE : DIMR);  rhoMat.opacity = sph ? 1 : 0.45;
  orangeDashMat.color.set(cyl ? HILITE : (rect ? 0xaaaaaa : ORANGE));
  sqMat.color.set(cyl ? HILITE : (rect ? 0xaaaaaa : ORANGE));
  phiMat.color.set(sph ? DARK : GREY);
  thetaMat.color.set(cyl ? HILITE : (sph ? DARK : GREY));
  helpers.forEach(h => h.visible = rect);
  lblRho.div.style.color = sph ? '#1a5caa' : '#9db7d4';
  lblPhi.div.style.color = sph ? '#333' : '#bbb';
  lblTheta.div.style.color = cyl ? '#cc5500' : (sph ? '#333' : '#bbb');
  const rc = rect ? '#999' : (cyl ? '#ff7f00' : '#c9722e');
  lblZ.div.style.color = rc;  lblR.div.style.color = rc;
  renderReadout();
}

/* ── Build static label entries (dummy positions filled by update) ────── */
addLabel('<i>x</i>', ptX);
addLabel('<i>y</i>', ptY);
addLabel('<i>z</i>', ptZ);
const lblP   = addLabel('P(x, y, z)<br>P(&rho;, &theta;, &phi;)', ORIGIN, { fontSize: '14px', offset: [52, -6] });
const lblRho = addLabel('<i>&rho;</i>', ORIGIN, { color: '#1a5caa', fontSize: '14px' });
const lblPhi = addLabel('<i>&phi;</i>', ORIGIN, { color: '#333', fontSize: '14px', offset: [8, 0] });
const lblTheta = addLabel('<i>&theta;</i>', ORIGIN, { color: '#333', fontSize: '14px' });
const lblZ = addLabel('<i>z</i>', ORIGIN, { color: '#c9722e', offset: [14, 0] });
const lblR = addLabel('<i>r</i>', ORIGIN, { color: '#c9722e', offset: [0, 12] });

update();
setCameraView({ projection: 'perspective', azimuthDeg: 25, elevationDeg: 18, rollDeg: 0, heightFraction: 0.65 });

/* ── Interactions — sliders ───────────────────────────────────────────── */
const el = id => document.getElementById(id);
function syncSliders() {
  el('rho').value = state.rho;   el('sv-rho').textContent = (+state.rho).toFixed(1);
  el('theta').value = state.theta; el('sv-theta').textContent = Math.round(state.theta) + '°';
  el('phi').value = state.phi;   el('sv-phi').textContent = Math.round(state.phi) + '°';
}
el('rho').addEventListener('input', e => { state.rho = +e.target.value; syncSliders(); update(); });
el('theta').addEventListener('input', e => { state.theta = +e.target.value; syncSliders(); update(); });
