(function tick() {
  requestAnimationFrame(tick);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k * k * (3 - 2 * k);                       // smoothstep
  let dT = (tween.to.theta - tween.from.theta) % 360;  // shortest wrap for θ
  dT = ((dT + 540) % 360) - 180;
  state.rho   = tween.from.rho + (tween.to.rho - tween.from.rho) * e;
  state.theta = tween.from.theta + dT * e;
  state.phi   = tween.from.phi + (tween.to.phi - tween.from.phi) * e;
  syncSliders(); update();
  if (k >= 1) tween = null;
})();

