function makeDashChain(mat, radius) {
  const group = new THREE.Group();
  scene.add(group);
  const segs = [];
  for (let i = 0; i < 48; i++) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 8), mat);
    m.visible = false; group.add(m); segs.push(m);
