  const _d = new THREE.Vector3();
  return {
    group,
    set(a, b, dashLen = 0.20, gap = 0.13) {
      _d.subVectors(b, a);
      const L = _d.length();
      if (L < 1e-6) { segs.forEach(s => s.visible = false); return; }
      const dir = _d.clone().normalize();
      const period = dashLen + gap;
      const n = Math.min(segs.length, Math.max(1, Math.floor(L / period)));
