  return { x: r * Math.cos(th), y: r * Math.sin(th), z: state.rho * Math.cos(ph), r, th, ph };
}

function update() {
  const { x, y, z, r, th, ph } = figCoords();
  const Pw = new THREE.Vector3(x, z, y);          // fig (x,y,z) → world (x, z, y)
  const Fw = new THREE.Vector3(x, 0, y);          // foot (x, y, 0)
  pMesh.position.copy(Pw);
  rhoCyl.visible = state.rho > 0.05;
  if (rhoCyl.visible) setRod(rhoCyl, ORIGIN, Pw);
  dropChain.set(Pw, Fw);
  groundChain.set(ORIGIN, Fw);

  // right-angle square at the foot
  const u = r > 1e-6 ? Fw.clone().negate().normalize() : new THREE.Vector3(1, 0, 0);
  const v = UPW.clone().multiplyScalar(z >= 0 ? 1 : -1).multiplyScalar(SQ);
  const uS = u.clone().multiplyScalar(SQ);
  setSquare(Fw.clone(), Fw.clone().add(uS),
    Fw.clone().add(uS).clone().add(v), Fw.clone().add(v));

  // φ arc (z-axis → OP), radius ARC_R
  const op = Pw.clone().normalize();
  let perp = op.clone().addScaledVector(UPW, -op.dot(UPW));
  if (perp.lengthSq() < 1e-8) perp.set(1, 0, 0);
  perp.normalize();
  const Np = Math.max(2, Math.round(70 * ph));
  const phiPts = [];
  for (let i = 0; i <= Np; i++) {
    const t = ph * i / Np;
    phiPts.push(UPW.clone().multiplyScalar(Math.cos(t))
      .addScaledVector(perp, Math.sin(t)).multiplyScalar(ARC_R));
  }
  phiArc.setPoints(phiPts);
  {
    const T = UPW.clone().multiplyScalar(-Math.sin(ph))
      .addScaledVector(perp, Math.cos(ph)).normalize();
    phiArrow.quaternion.setFromUnitVectors(UPW, T);
    phiArrow.position.copy(UPW.clone().multiplyScalar(Math.cos(ph))
      .addScaledVector(perp, Math.sin(ph)).multiplyScalar(ARC_R));
    lblPhi.pos.copy(UPW.clone().multiplyScalar(Math.cos(ph / 2))
      .addScaledVector(perp, Math.sin(ph / 2)).multiplyScalar(ARC_R * 1.55));
  }

  // θ arc (x-axis → ground segment) in the xy-plane
  const Nt = Math.max(2, Math.round(70 * th));
  const thetaPts = [];
  for (let i = 0; i <= Nt; i++) {
    const a = th * i / Nt;
    thetaPts.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a)).multiplyScalar(ARC_R));
  }
  thetaArc.setPoints(thetaPts);
  {
    const T = new THREE.Vector3(-Math.sin(th), 0, Math.cos(th)).normalize();
    thetaArrow.quaternion.setFromUnitVectors(UPW, T);
    thetaArrow.position.set(Math.cos(th), 0, Math.sin(th)).multiplyScalar(ARC_R);
    lblTheta.pos.set(Math.cos(th / 2), 0, Math.sin(th / 2)).multiplyScalar(ARC_R * 1.55);
  }

  // labels that track the point
  lblP.pos.copy(Pw);
  lblRho.pos.copy(Pw).multiplyScalar(0.5).addScaledVector(UPW, 0.42);
  lblZ.pos.copy(Pw).lerp(Fw, 0.5);
  lblR.pos.copy(Fw).multiplyScalar(0.5);

  // rectangular helper lines: P → each axis
  setDashed(helpers[0], Pw, new THREE.Vector3(x, 0, 0));
  setDashed(helpers[1], Pw, new THREE.Vector3(0, 0, y));
  setDashed(helpers[2], Pw, new THREE.Vector3(0, z, 0));
  renderReadout();
}

/* ── Mode highlight + readout ─────────────────────────────────────────── */
const readout = document.getElementById('readout');
function renderReadout() {
  const { x, y, z, r } = figCoords();
  const f = (v, d = 2) => v.toFixed(d);
  readout.innerHTML =
    mode === 'rect'  ? `x = ${f(x)}<br>y = ${f(y)}<br>z = ${f(z)}` :
    mode === 'cyl'   ? `r = ${f(r)}<br>θ = ${f(state.theta, 0)}°<br>z = ${f(z)}` :
                       `ρ = ${f(state.rho)}<br>θ = ${f(state.theta, 0)}°<br>φ = ${f(state.phi, 0)}°`;
}
function setMode(m) {
  mode = m;
  const sph = m === 'sph', cyl = m === 'cyl', rect = m === 'rect';
  [['cs-rect', 'rect'], ['cs-cyl', 'cyl'], ['cs-sph', 'sph']].forEach(([id, k]) =>
