// @FIGURE_CODE_BEGIN
/* ── Element spec (one primitive per visible element) ──────────────────────
// x-axis → Line + ConeGeometry arrowhead, #222, fig +X → world +X, len 5.5 (drawn lower-LEFT on screen)
// y-axis → Line + Cone, fig +Y → world +Z, len 5.5 (drawn to the RIGHT)
// z-axis → Line + Cone, fig +Z → world +Y, len 5.5 (drawn straight UP)
// P       → SphereGeometry(0.09) black at (ρ sinφ cosθ, ρ sinφ sinθ, ρ cosφ)
// P label → two-line addLabel right of P: 'P(x, y, z)' / 'P(ρ, θ, φ)' BIG BOLD serif
// ρ line  → CylinderGeometry origin→P, #1a5caa, radius 0.055 (thick blue rod)
// φ arc   → tube segment chain (r=1.2) + cone arrowhead, z-axis → OP
// θ arc   → tube segment chain (r=1.2) in xy-plane + cone arrowhead, x → ground seg
// z drop  → dashed orange cylinder chain, P → (x, y, 0)
// r line  → dashed orange cylinder chain, origin → (x, y, 0)
// square  → 4-seg cylinder chain at foot, side 0.25
// helpers → 3 dashed grey lines P→axis (rectangular mode only)
*/
const UPW = new THREE.Vector3(0, 1, 0);      // figure +z in world space
const ORIGIN = new THREE.Vector3(0, 0, 0);
const AXIS_LEN = 5.5, ARC_R = 1.2, SQ = 0.25;
const BLUE = 0x1a5caa, ORANGE = 0xe07b2a, HILITE = 0xff7f00,
      DIMR = 0xb9cfe3, GREY = 0xbbbbbb, DARK = 0x333333;

const state = { rho: 4, theta: 40, phi: 50 };
let mode = 'sph';   // 'rect' | 'cyl' | 'sph'

/* ── Axes ─────────────────────────────────────────────────────────────── */
function makeAxis(fx, fy, fz) {
  const dir = new THREE.Vector3(fx, fz, fy).normalize();  // (x,z,y): fig→world
  const g = new THREE.Group();
  const mat = new THREE.LineBasicMaterial({ color: 0x222222 });
  g.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(
      [ORIGIN.clone(), dir.clone().multiplyScalar(AXIS_LEN)]), mat));
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.28, 16),
    new THREE.MeshBasicMaterial({ color: 0x222222 }));
  cone.position.copy(dir).multiplyScalar(AXIS_LEN + 0.14);
  cone.quaternion.setFromUnitVectors(UPW, dir);
  g.add(cone);
  scene.add(g);
  return dir.clone().multiplyScalar(AXIS_LEN + 0.5);
}
const ptX = makeAxis(1, 0, 0), ptY = makeAxis(0, 1, 0), ptZ = makeAxis(0, 0, 1);

/* ── Static / reactive meshes ─────────────────────────────────────────── */
const pMesh = new THREE.Mesh(new THREE.SphereGeometry(0.09, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));          scene.add(pMesh);

const rhoMat = new THREE.MeshBasicMaterial({ color: BLUE, transparent: true });
const rhoCyl = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 1, 12), rhoMat);
scene.add(rhoCyl);

/* Dashed "thick line" = chain of short cylinders (real stroke weight). */
function makeDashChain(mat, radius) {
  const group = new THREE.Group();
  scene.add(group);
  const segs = [];
  for (let i = 0; i < 48; i++) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 8), mat);
    m.visible = false; group.add(m); segs.push(m);
  }
  const _d = new THREE.Vector3();
  return {
    group,
    set(a, b, dashLen = 0.20, gap = 0.13) {
      _d.subVectors(b, a);
      const L = _d.length();
      if (L < 1e-6) { segs.forEach(s => s.visible = false); return; }
      const dir = _d.clone().normalize();
      const period = dashLen + gap;
      const n = Math.min(segs.length, Math.max(1, Math.floor(L / period)));
      for (let i = 0; i < segs.length; i++) {
        const s = segs[i];
        if (i < n) {
          const mid = a.clone().addScaledVector(dir, i * period + dashLen / 2);
          s.position.copy(mid);
          s.quaternion.setFromUnitVectors(UPW, dir);
          s.scale.set(1, Math.min(dashLen, Math.max(0.02, L - i * period)), 1);
          s.visible = true;
        } else s.visible = false;
      }
    }
  };
}
const orangeDashMat = new THREE.MeshBasicMaterial({ color: ORANGE, transparent: true });
const dropChain   = makeDashChain(orangeDashMat, 0.024);   // z drop
const groundChain = makeDashChain(orangeDashMat, 0.024);   // r line

/* Right-angle square at the foot */
const sqMat = new THREE.MeshBasicMaterial({ color: ORANGE, transparent: true });
const squareGroup = new THREE.Group(); scene.add(squareGroup);
const sqSegs = [];
for (let i = 0; i < 4; i++) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, SQ, 8), sqMat);
  squareGroup.add(m); sqSegs.push(m);
}
function setSquare(p0, p1, p2, p3) {
  const pts = [p0, p1, p2, p3];
  for (let i = 0; i < 4; i++) {
    const a = pts[i], b = pts[(i + 1) % 4];
    const d = b.clone().sub(a);
    sqSegs[i].position.copy(a).addScaledVector(d, 0.5);
    sqSegs[i].quaternion.setFromUnitVectors(UPW, d.normalize());
  }
}

/* Arcs as tube segment chains (visible stroke weight). */
function makeArc(mat, radius = 0.02) {
  const group = new THREE.Group(); scene.add(group);
  const segs = [];
  for (let i = 0; i < 90; i++) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 6), mat);
    m.visible = false; group.add(m); segs.push(m);
  }
  return {
    group,
    setPoints(pts) {
      for (let i = 0; i < segs.length; i++) {
        const s = segs[i];
        if (i < pts.length - 1) {
          const a = pts[i], b = pts[i + 1];
          const d = b.clone().sub(a);
          s.position.copy(a).addScaledVector(d, 0.5);
          s.quaternion.setFromUnitVectors(UPW, d.clone().normalize());
          s.scale.set(1, d.length(), 1);
          s.visible = true;
        } else s.visible = false;
      }
    }
  };
}
const phiMat   = new THREE.MeshBasicMaterial({ color: DARK });
const thetaMat = new THREE.MeshBasicMaterial({ color: DARK });
const phiArc   = makeArc(phiMat);
const thetaArc = makeArc(thetaMat);

function makeArcArrow(mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.16, 10), mat);
  scene.add(m); return m;
}
const phiArrow = makeArcArrow(phiMat), thetaArrow = makeArcArrow(thetaMat);

const helperMat = new THREE.LineDashedMaterial({ color: 0x999999, dashSize: 0.14, gapSize: 0.10, transparent: true });
const helpers = [0, 1, 2].map(() => {
  const l = new THREE.Line(new THREE.BufferGeometry(), helperMat);
  l.visible = false; scene.add(l); return l;
});

function setDashed(line, a, b) {
  line.geometry.setFromPoints([a.clone(), b.clone()]);
  line.computeLineDistances();
}
const _dir = new THREE.Vector3();
function setRod(mesh, a, b) {
  _dir.subVectors(b, a);
  const len = Math.max(_dir.length(), 1e-6);
  mesh.position.copy(a).addScaledVector(_dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UPW, _dir.clone().normalize());
  mesh.scale.set(1, len, 1);
}

/* ── Reactive update ──────────────────────────────────────────────────── */
function figCoords() {
  const th = THREE.MathUtils.degToRad(state.theta);
  const ph = THREE.MathUtils.degToRad(state.phi);
  const r = state.rho * Math.sin(ph);
  return { x: r * Math.cos(th), y: r * Math.sin(th), z: state.rho * Math.cos(ph), r, th, ph };
}

function update() {
  const { x, y, z, r, th, ph } = figCoords();
  const Pw = new THREE.Vector3(x, z, y);          // fig (x,y,z) → world (x, z, y)
  const Fw = new THREE.Vector3(x, 0, y);          // foot (x, y, 0)
  pMesh.position.copy(Pw);
  rhoCyl.visible = state.rho > 0.05;
  if (rhoCyl.visible) setRod(rhoCyl, ORIGIN, Pw);
  dropChain.set(Pw, Fw);
  groundChain.set(ORIGIN, Fw);

  // right-angle square at the foot
  const u = r > 1e-6 ? Fw.clone().negate().normalize() : new THREE.Vector3(1, 0, 0);
  const v = UPW.clone().multiplyScalar(z >= 0 ? 1 : -1).multiplyScalar(SQ);
  const uS = u.clone().multiplyScalar(SQ);
  setSquare(Fw.clone(), Fw.clone().add(uS),
    Fw.clone().add(uS).clone().add(v), Fw.clone().add(v));

  // φ arc (z-axis → OP), radius ARC_R
  const op = Pw.clone().normalize();
  let perp = op.clone().addScaledVector(UPW, -op.dot(UPW));
  if (perp.lengthSq() < 1e-8) perp.set(1, 0, 0);
  perp.normalize();
  const Np = Math.max(2, Math.round(70 * ph));
  const phiPts = [];
  for (let i = 0; i <= Np; i++) {
    const t = ph * i / Np;
    phiPts.push(UPW.clone().multiplyScalar(Math.cos(t))
      .addScaledVector(perp, Math.sin(t)).multiplyScalar(ARC_R));
  }
  phiArc.setPoints(phiPts);
  {
    const T = UPW.clone().multiplyScalar(-Math.sin(ph))
      .addScaledVector(perp, Math.cos(ph)).normalize();
    phiArrow.quaternion.setFromUnitVectors(UPW, T);
    phiArrow.position.copy(UPW.clone().multiplyScalar(Math.cos(ph))
      .addScaledVector(perp, Math.sin(ph)).multiplyScalar(ARC_R));
    lblPhi.pos.copy(UPW.clone().multiplyScalar(Math.cos(ph / 2))
      .addScaledVector(perp, Math.sin(ph / 2)).multiplyScalar(ARC_R * 1.55));
  }

  // θ arc (x-axis → ground segment) in the xy-plane
  const Nt = Math.max(2, Math.round(70 * th));
  const thetaPts = [];
  for (let i = 0; i <= Nt; i++) {
    const a = th * i / Nt;
    thetaPts.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a)).multiplyScalar(ARC_R));
  }
  thetaArc.setPoints(thetaPts);
  {
    const T = new THREE.Vector3(-Math.sin(th), 0, Math.cos(th)).normalize();
    thetaArrow.quaternion.setFromUnitVectors(UPW, T);
    thetaArrow.position.set(Math.cos(th), 0, Math.sin(th)).multiplyScalar(ARC_R);
    lblTheta.pos.set(Math.cos(th / 2), 0, Math.sin(th / 2)).multiplyScalar(ARC_R * 1.55);
  }

  // labels that track the point
  lblP.pos.copy(Pw);
  lblRho.pos.copy(Pw).multiplyScalar(0.5).addScaledVector(UPW, 0.42);
  lblZ.pos.copy(Pw).lerp(Fw, 0.5);
  lblR.pos.copy(Fw).multiplyScalar(0.5);

  // rectangular helper lines: P → each axis
  setDashed(helpers[0], Pw, new THREE.Vector3(x, 0, 0));
  setDashed(helpers[1], Pw, new THREE.Vector3(0, 0, y));
  setDashed(helpers[2], Pw, new THREE.Vector3(0, z, 0));
  renderReadout();
}

/* ── Mode highlight + readout ─────────────────────────────────────────── */
const readout = document.getElementById('readout');
function renderReadout() {
  const { x, y, z, r } = figCoords();
  const f = (v, dd = 2) => v.toFixed(dd);
  readout.innerHTML =
    mode === 'rect'  ? `x = ${f(x)}<br>y = ${f(y)}<br>z = ${f(z)}` :
    mode === 'cyl'   ? `r = ${f(r)}<br>θ = ${f(state.theta, 0)}°<br>z = ${f(z)}` :
                       `ρ = ${f(state.rho)}<br>θ = ${f(state.theta, 0)}°<br>φ = ${f(state.phi, 0)}°`;
}
function setMode(m) {
  mode = m;
  const sph = m === 'sph', cyl = m === 'cyl', rect = m === 'rect';
  [['cs-rect', 'rect'], ['cs-cyl', 'cyl'], ['cs-sph', 'sph']].forEach(([id, k]) =>
    document.getElementById(id).classList.toggle('active', k === m));
  rhoMat.color.set(sph ? BLUE : DIMR);  rhoMat.opacity = sph ? 1 : 0.45;
  orangeDashMat.color.set(cyl ? HILITE : (rect ? 0xaaaaaa : ORANGE));
  sqMat.color.set(cyl ? HILITE : (rect ? 0xaaaaaa : ORANGE));
  phiMat.color.set(sph ? DARK : GREY);
  thetaMat.color.set(cyl ? HILITE : (sph ? DARK : GREY));
  helpers.forEach(h => h.visible = rect);
  lblRho.div.style.color = sph ? '#1a5caa' : '#9db7d4';
  lblPhi.div.style.color = sph ? '#333' : '#bbb';
  lblTheta.div.style.color = cyl ? '#cc5500' : (sph ? '#333' : '#bbb');
  const rc = rect ? '#999' : (cyl ? '#ff7f00' : '#c9722e');
  lblZ.div.style.color = rc;  lblR.div.style.color = rc;
  renderReadout();
}

/* ── Labels — large, bold, serif to match the source typography ────────── */
const SERIF = "Georgia, 'Times New Roman', serif";
function styleSerif(entry) { entry.div.style.fontFamily = SERIF; return entry; }
addLabel('<i>x</i>', ptX, { fontSize: '24px', bold: true }).div.style.fontFamily = SERIF;
addLabel('<i>y</i>', ptY, { fontSize: '24px', bold: true }).div.style.fontFamily = SERIF;
addLabel('<i>z</i>', ptZ, { fontSize: '24px', bold: true }).div.style.fontFamily = SERIF;
const lblP = addLabel('P(<i>x</i>, <i>y</i>, <i>z</i>)<br>P(<i>&rho;</i>, <i>&theta;</i>, <i>&phi;</i>)',
  ORIGIN, { fontSize: '28px', bold: true, offset: [105, -20] });
styleSerif(lblP); lblP.div.style.lineHeight = '1.3';
const lblRho = styleSerif(addLabel('<i>&rho;</i>', ORIGIN, { color: '#1a5caa', fontSize: '26px', bold: true }));
const lblPhi = styleSerif(addLabel('<i>&phi;</i>', ORIGIN, { color: '#333', fontSize: '22px', bold: true, offset: [10, 0] }));
const lblTheta = styleSerif(addLabel('<i>&theta;</i>', ORIGIN, { color: '#333', fontSize: '22px', bold: true }));
const lblZ = styleSerif(addLabel('<i>z</i>', ORIGIN, { color: '#c9722e', fontSize: '22px', bold: true, offset: [20, 0] }));
const lblR = styleSerif(addLabel('<i>r</i>', ORIGIN, { color: '#c9722e', fontSize: '22px', bold: true, offset: [0, 18] }));

update();
/* Azimuth 205° puts fig +x (world +X) to the lower-LEFT and fig +y (world +Z)
   to the RIGHT — matching the source handedness. Short axes + high
   heightFraction make P and the construction fill the frame. */
setCameraView({ projection: 'perspective', azimuthDeg: 205, elevationDeg: 18, rollDeg: 0, heightFraction: 0.8 });

/* ── Interactions — sliders ───────────────────────────────────────────── */
const el = id => document.getElementById(id);
function syncSliders() {
  el('rho').value = state.rho;   el('sv-rho').textContent = (+state.rho).toFixed(1);
  el('theta').value = state.theta; el('sv-theta').textContent = Math.round(state.theta) + '°';
  el('phi').value = state.phi;   el('sv-phi').textContent = Math.round(state.phi) + '°';
}
el('rho').addEventListener('input', e => { state.rho = +e.target.value; syncSliders(); update(); });
el('theta').addEventListener('input', e => { state.theta = +e.target.value; syncSliders(); update(); });
el('phi').addEventListener('input', e => { state.phi = +e.target.value; syncSliders(); update(); });
el('cs-rect').addEventListener('click', () => setMode('rect'));
el('cs-cyl').addEventListener('click', () => setMode('cyl'));
el('cs-sph').addEventListener('click', () => setMode('sph'));

/* ── Demo steps (goToStep tweens the sliders) ─────────────────────────── */
const STEPS = [
  { title: 'Spherical description',
    narration: 'With the spherical readout active, ρ, θ, and φ are highlighted: one distance from the origin plus two angles fix P. Note the φ arc measured down from the z-axis and the θ arc in the xy-plane.',
    state: { rho: 4, theta: 40, phi: 50, coordSystem: 'sph' } },
  { title: 'Change the polar angle',
    narration: 'Reduce φ toward 20°. P swings up toward the z-axis: the vertical height z = ρ cos φ grows while the ground projection r = ρ sin φ shrinks.',
    state: { rho: 4, theta: 40, phi: 20, coordSystem: 'sph' } },
  { title: 'Same point, cylindrical readout',
    narration: 'Switch to cylindrical. The point does not move — only the description changes: r, θ, z are highlighted, showing θ and the geometry of r and z are shared between systems.',
    state: { rho: 4, theta: 40, phi: 20, coordSystem: 'cyl' } },
  { title: 'Rectangular readout',
    narration: 'Switch to rectangular: x = ρ sin φ cos θ, y = ρ sin φ sin θ, z = ρ cos φ. All three descriptions name the same dot in space.',
    state: { rho: 4, theta: 40, phi: 20, coordSystem: 'rect' } },
];
let tween = null;
function goToStep(i) {
  const s = STEPS[i];
  if (s.state.coordSystem) setMode(s.state.coordSystem);
  tween = {
    t0: performance.now(), dur: 900,
    from: { rho: state.rho, theta: state.theta, phi: state.phi },
    to: { rho: s.state.rho, theta: s.state.theta, phi: s.state.phi },
  };
  document.getElementById('narration').textContent = s.narration;
}
STEPS.forEach((s, i) => el('ds' + i).addEventListener('click', () => goToStep(i)));
window.goToStep = goToStep;
(function tick() {
  requestAnimationFrame(tick);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k * k * (3 - 2 * k);                       // smoothstep
  let dT = (tween.to.theta - tween.from.theta) % 360;  // shortest wrap for θ
  dT = ((dT + 540) % 360) - 180;
  state.rho   = tween.from.rho + (tween.to.rho - tween.from.rho) * e;
  state.theta = tween.from.theta + dT * e;
  state.phi   = tween.from.phi + (tween.to.phi - tween.from.phi) * e;
  syncSliders(); update();
  if (k >= 1) tween = null;
})();

